243	    const titleAttr = title ? ` title="${escapeHtml(title)}"` : "";
244	    return `<img src="${escapeHtml(safe)}" alt="${escapeHtml(text)}"${titleAttr}>`;
245	  };
246	  return marked.parse(markdown, {
247	    async: false,
248	    breaks: true,
249	    gfm: true,
250	    renderer,
251	  }) as string;
252	}
253	
254	function markdownContent(value: UnknownRecord): string | null {
255	  const content = recordObject(value.content);
256	  if (content?.$type !== "at.markpub.markdown") return null;
257	  const text = recordObject(content.text);
258	  return stringField(text ?? {}, "markdown");
259	}
260	
261	function documentSummary(
262	  did: string,
263	  publicationRkey: string,
264	  uri: string,
265	  value: UnknownRecord,
266	): StandardSiteDocumentSummary | null {
267	  const match = /^at:\/\/[^/]+\/site\.standard\.document\/([^/?#]+)$/.exec(uri);
268	  const rkey = match?.[1] ?? "";
269	  if (!isTid(rkey)) return null;
270	  const expectedSite = publicationAtUri(did, publicationRkey);
271	  const expectedPath = standardSiteDocumentPath(rkey);
272	  const title = stringField(value, "title")?.trim();
273	  const publishedAt = stringField(value, "publishedAt");
274	  if (
275	    value.$type !== STANDARD_SITE_DOCUMENT_COLLECTION ||
276	    value.site !== expectedSite ||
277	    value.path !== expectedPath ||
278	    !title ||
279	    !publishedAt ||
280	    Number.isNaN(Date.parse(publishedAt))
281	  ) {
282	    return null;
283	  }
284	  return {
285	    uri: documentAtUri(did, rkey),
286	    rkey,
287	    title,
288	    description: stringField(value, "description")?.trim() || null,
289	    publishedAt,
290	    updatedAt: stringField(value, "updatedAt"),
291	    url: standardSiteDocumentUrl(did, publicationRkey, rkey),
292	  };
293	}
294	
295	export function standardSiteRouteDid(segment: string): string {
296	  const did = decodeStandardSiteDid(segment);
297	  if (!did) throw new Error("Invalid ATProto DID route");
298	  return did;
299	}
300	
301	export async function loadStandardSitePublication(
302	  did: string,
303	  publicationRkey: string,
304	  fetcher: Fetcher = fetch,
305	): Promise<StandardSitePublicationPage> {
306	  if (!isTid(publicationRkey)) throw new Error("Invalid publication key");
307	  const pds = await resolvePds(did, fetcher);
308	  const publicationValue = await getRecord(
309	    did,
310	    STANDARD_SITE_PUBLICATION_COLLECTION,
311	    publicationRkey,
312	    fetcher,
313	    pds,
314	  );
315	  const publication = parsePublication(did, publicationRkey, publicationValue);
316	  const records = await listDocumentRecords(did, fetcher, pds);
317	  const documents = records
318	    .map(({ uri, value }) => documentSummary(did, publicationRkey, uri, value))
319	    .filter((document): document is StandardSiteDocumentSummary => !!document)
320	    .sort((a, b) => Date.parse(b.publishedAt) - Date.parse(a.publishedAt));
321	  return { publication, documents };
322	}
323	
324	export async function loadStandardSiteDocument(
325	  did: string,
326	  publicationRkey: string,
327	  documentRkey: string,
328	  fetcher: Fetcher = fetch,
329	): Promise<StandardSiteDocumentPage> {
330	  if (!isTid(publicationRkey) || !isTid(documentRkey)) {
331	    throw new Error("Invalid Standard.site record key");
332	  }
333	  const pds = await resolvePds(did, fetcher);
334	  const [publicationValue, documentValue] = await Promise.all([
335	    getRecord(
336	      did,
337	      STANDARD_SITE_PUBLICATION_COLLECTION,
338	      publicationRkey,
339	      fetcher,
340	      pds,
341	    ),
342	    getRecord(
343	      did,
344	      STANDARD_SITE_DOCUMENT_COLLECTION,
345	      documentRkey,
346	      fetcher,
347	      pds,
348	    ),
349	  ]);
350	  const publication = parsePublication(did, publicationRkey, publicationValue);
351	  const uri = documentAtUri(did, documentRkey);
352	  const summary = documentSummary(did, publicationRkey, uri, documentValue);
353	  if (!summary)
354	    throw new Error("Standard.site document is not verified for this URL");
355	  const markdown = markdownContent(documentValue);
356	  const textContent = stringField(documentValue, "textContent") ?? "";
357	  const html = markdown
358	    ? renderStandardSiteMarkdown(markdown)
359	    : `<p>${escapeHtml(textContent)
360	        .replace(/\n{2,}/g, "</p><p>")
361	        .replace(/\n/g, "<br>")}</p>`;
362	  return {
363	    publication,
364	    document: { ...summary, textContent, markdown, html },
365	  };
366	}

